from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            moves = 0
            carry = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p
                if carry >= need:
                    carry = 0
                    moves += 1
                else:
                    extra = need - carry
                    moves += 2 * extra - 1
                    carry = extra - 1

                if moves > m:
                    return False

            return moves <= m

        low, high = 0, min(points) * m
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if can(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans
